from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    result = []

    for group in paren_string.split():
        depth = 0
        max_depth = 0

        for char in group:
            if char == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif char == ')':
                depth -= 1

        result.append(max_depth)

    return result
```

