def flip_case(string: str) -> str:
    """ for a given string, flip lowercase character to uppercase and uppercase to lowercase.
    >>>flip_case('Hello')
    'hELLO'
    """
    result = []
    for char in string:
        if char.islower():
            result.append(char.upper())
        elif char.isupper():
            result.append(char.lower())
        else:
            result.append(char)
    return ''.join(result)
```

