def intersection(interval1, interval2):
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    length = end - start

    if length < 2:
        return "NO"

    if length % 2 == 0:
        return "YES" if length == 2 else "NO"

    if length % 3 == 0:
        return "YES" if length == 3 else "NO"

    i = 5
    while i * i <= length:
        if length % i == 0 or length % (i + 2) == 0:
            return "NO"
        i += 6

    return "YES"
